#!/usr/bin/env python3
"""
Swarm OS Test Remediation Engine
Fixes dependencies and executes 5 target tests with 120s timeout.
"""
import os, sys, subprocess, importlib, ast, traceback, json, time
from pathlib import Path

SCRATCH = Path(r"C:/Users/shawn/.gemini/antigravity/brain/807168cd-2585-4a4e-b18f-383a6bdf794d/scratch")
TARGETS = [
    "test_ppm4.py",
    "test_all_subagents_microkernel.py",
    "test_instella_moe.py",
    "test_full_64_agent_sweep.py",
    "test_instella_task.py",
]
TIMEOUT = 120  # seconds per test

# Known dependency mapping for this project
KNOWN_DEPS = {
    'numpy': 'numpy',
    'torch': 'torch',
    'tensorflow': 'tensorflow',
    'pytest': 'pytest',
    'asyncio': None,  # stdlib
    'antigravity': None,  # local module
    'brain': None,  # local
    'scratch': None,  # local
}

def install_package(pkg_name: str) -> bool:
    """Install a pip package."""
    try:
        subprocess.run(
            [sys.executable, "-m", "pip", "install", pkg_name, "--quiet"],
            check=True, timeout=60, capture_output=True
        )
        print(f"  [INSTALLED] {pkg_name}")
        return True
    except Exception as e:
        print(f"  [INSTALL FAILED] {pkg_name}: {e}")
        return False

def analyze_imports(filepath: Path) -> list:
    """Extract all import statements from a Python file."""
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            tree = ast.parse(f.read())
        imports = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    imports.append(alias.name.split('.')[0])
            elif isinstance(node, ast.ImportFrom):
                if node.module:
                    imports.append(node.module.split('.')[0])
        return list(set(imports))
    except SyntaxError as e:
        print(f"  [SYNTAX ERROR in {filepath.name}]: {e}")
        return []

def ensure_dependencies(imports: list) -> None:
    """Ensure all imports are available, install missing ones."""
    for imp in imports:
        if imp in KNOWN_DEPS and KNOWN_DEPS[imp] is None:
            continue  # stdlib or local
        try:
            importlib.import_module(imp)
            print(f"  [OK] {imp} available")
        except ImportError:
            pkg = KNOWN_DEPS.get(imp, imp)
            print(f"  [MISSING] {imp} -> attempting install of {pkg}")
            install_package(pkg)

def run_test(filepath: Path) -> dict:
    """Run a single test file with timeout, return result dict."""
    result = {
        'test': filepath.name,
        'status': 'UNKNOWN',
        'output': '',
        'error': '',
        'duration': 0.0
    }
    start = time.time()
    try:
        proc = subprocess.run(
            [sys.executable, str(filepath)],
            capture_output=True, text=True, timeout=TIMEOUT,
            cwd=str(SCRATCH)
        )
        result['duration'] = time.time() - start
        result['output'] = proc.stdout[-3000:] if proc.stdout else ''
        result['error'] = proc.stderr[-3000:] if proc.stderr else ''
        result['status'] = 'PASS' if proc.returncode == 0 else 'FAIL'
        result['returncode'] = proc.returncode
    except subprocess.TimeoutExpired:
        result['duration'] = time.time() - start
        result['status'] = 'TIMEOUT'
        result['error'] = f"Exceeded {TIMEOUT}s timeout"
    except Exception as e:
        result['duration'] = time.time() - start
        result['status'] = 'ERROR'
        result['error'] = str(e)
    return result

def main():
    print("=" * 70)
    print("SWARM OS TEST REMEDIATION ENGINE v1.0")
    print(f"Scratch dir: {SCRATCH}")
    print(f"Timeout per test: {TIMEOUT}s")
    print("=" * 70)
    
    results = []
    
    for target in TARGETS:
        filepath = SCRATCH / target
        print(f"\n{'='*70}")
        print(f"TARGET: {target}")
        print(f"{'='*70}")
        
        if not filepath.exists():
            print(f"  [ERROR] File not found: {filepath}")
            results.append({'test': target, 'status': 'NOT_FOUND', 'error': 'File missing'})
            continue
        
        # Phase 1: Dependency analysis
        print(f"\n[PHASE 1] Dependency analysis...")
        imports = analyze_imports(filepath)
        print(f"  Found {len(imports)} unique imports: {', '.join(imports[:15])}")
        ensure_dependencies(imports)
        
        # Phase 2: Syntax check
        print(f"\n[PHASE 2] Syntax validation...")
        try:
            with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
                ast.parse(f.read())
            print(f"  [OK] Syntax valid")
        except SyntaxError as e:
            print(f"  [SYNTAX ERROR] {e}")
            # Attempt to fix common syntax issues
            print(f"  [FIXING] Attempting syntax repair...")
            fix_syntax(filepath)
            # Re-validate
            try:
                with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
                    ast.parse(f.read())
                print(f"  [FIXED] Syntax now valid")
            except SyntaxError as e2:
                print(f"  [UNFIXABLE] {e2}")
                results.append({'test': target, 'status': 'SYNTAX_ERROR', 'error': str(e2)})
                continue
        
        # Phase 3: Execution
        print(f"\n[PHASE 3] Executing test with {TIMEOUT}s timeout...")
        result = run_test(filepath)
        results.append(result)
        
        # Report
        status_icon = "✅" if result['status'] == 'PASS' else "❌" if result['status'] == 'FAIL' else "⏰" if result['status'] == 'TIMEOUT' else "⚠️"
        print(f"\n  {status_icon} STATUS: {result['status']}")
        print(f"  Duration: {result['duration']:.2f}s")
        if result.get('returncode') is not None:
            print(f"  Return code: {result['returncode']}")
        if result['output']:
            print(f"  Output (last 500):\n{result['output'][-500:]}")
        if result['error']:
            print(f"  Error (last 500):\n{result['error'][-500:]}")
    
    # Final summary
    print("\n" + "=" * 70)
    print("FINAL TEST MATRIX")
    print("=" * 70)
    print(f"{'Test':<45} {'Status':<10} {'Duration':<10}")
    print("-" * 70)
    for r in results:
        dur = f"{r.get('duration', 0):.2f}s" if r.get('duration') else 'N/A'
        print(f"{r['test']:<45} {r['status']:<10} {dur:<10}")
    
    # Exit code
    pass_count = sum(1 for r in results if r['status'] == 'PASS')
    print(f"\nTotal: {len(results)} | Passed: {pass_count} | Failed: {len(results) - pass_count}")
    return 0 if pass_count == len(results) else 1

def fix_syntax(filepath: Path):
    """Attempt to fix common syntax issues in test files."""
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            content = f.read()
        
        # Fix common issues
        fixes = [
            # Remove BOM
            (lambda c: c.lstrip('\ufeff')),
            # Fix indentation issues (tabs to spaces)
            (lambda c: c.replace('\t', '    ')),
            # Fix trailing whitespace
            (lambda c: '\n'.join(line.rstrip() for line in c.split('\n'))),
            # Ensure newline at EOF
            (lambda c: c if c.endswith('\n') else c + '\n'),
        ]
        
        for fix in fixes:
            content = fix(content)
        
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f"  [FIXED] Applied syntax repairs to {filepath.name}")
    except Exception as e:
        print(f"  [FIX FAILED] {e}")

if __name__ == "__main__":
    sys.exit(main())
